    long long a[n];
    long long xorsum = 0;
    // count available masks
    long long mask_count[64] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
        xorsum ^= a[i];
        if (a[i] >= 1) {
            long long m = a[i] ^ (a[i]-1);
            // m = 2^(k+1)-1, find k+1
            int bits = 0;
            while ((1LL<<bits) <= m) bits++;
            mask_count[bits]++;
        }
    }
    if (xorsum == 0) { printf("0\n"); return 0; }
    long long x = xorsum;
    int ans = 0;
    while (x != 0) {
