#define MIN(a,b) ((a)<(b)?(a):(b))

int main() {
    int n;
    scanf("%d", &n);
    int *a = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // dp maps xor value -> minimum stones taken
    // We'll use two arrays of structs: one for current, one for next.
    // Since n can be up to maybe 100, we can store up to 2^n states worst case,
    // but with xor merging, it's at most 2^31 different values? Not feasible.
    // But typical trick: Use hash map or only store reachable XORs.
    // For constraints up to 15, full enumeration works; for larger, we need smarter.
    // We'll assume N <= 15 for full enumeration, else use meet-in-the-middle.

    if (n <= 15) {
        int total_states = 1 << n;
        int best = INT_MAX;
        for (int mask = 0; mask < total_states; mask++) {
            int xor_val = 0;
            int stones = 0;
            int ok = 1;
            for (int i = 0; i < n; i++) {
                if ((mask >> i) & 1) {
                    if (a[i] == 0) { ok = 0; break; }
                    xor_val ^= (a[i] - 1);
                    stones += 1;
                } else {
                    xor_val ^= a[i];
                }
            }
            if (ok && xor_val == 0) {
                best = MIN(best, stones);
            }
        }
        if (best == INT_MAX) printf("-1\n");
        else printf("%d\n", best);
    } else {
        // Meet-in-the-middle approach for larger N
        int half = n / 2;
        int left_n = half;
        int right_n = n - half;

        // Left part enumeration
        int left_states = 1 << left_n;
        int *xor_left = malloc(left_states * sizeof(int));
        int *cost_left = malloc(left_states * sizeof(int));
        for (int mask = 0; mask < left_states; mask++) {
            int x = 0, c = 0, ok = 1;
            for (int i = 0; i < left_n; i++) {
                if ((mask >> i) & 1) {
                    if (a[i] == 0) { ok = 0; break; }
                    x ^= (a[i] - 1);
                    c++;
                } else {
                    x ^= a[i];
                }
            }
            if (ok) {
                xor_left[mask] = x;
                cost_left[mask] = c;
            } else {
                xor_left[mask] = -1;
            }
        }

        // Right part enumeration
        int right_states = 1 << right_n;
        int *xor_right = malloc(right_states * sizeof(int));
        int *cost_right = malloc(right_states * sizeof(int));
        for (int mask = 0; mask < right_states; mask++) {
            int x = 0, c = 0, ok = 1;
            for (int i = 0; i < right_n; i++) {
                if ((mask >> i) & 1) {
                    if (a[left_n + i] == 0) { ok = 0; break; }
                    x ^= (a[left_n + i] - 1);
                    c++;
                } else {
                    x ^= a[left_n + i];
                }
            }
            if (ok) {
                xor_right[mask] = x;
                cost_right[mask] = c;
            } else {
                xor_right[mask] = -1;
            }
        }

        // For each left mask, we want a right mask with xor = xor_left[mask]
        // So that total xor = 0
        int best = INT_MAX;
        for (int l = 0; l < left_states; l++) {
            if (xor_left[l] == -1) continue;
            for (int r = 0; r < right_states; r++) {
                if (xor_right[r] == -1) continue;
                if ((xor_left[l] ^ xor_right[r]) == 0) {
                    best = MIN(best, cost_left[l] + cost_right[r]);
                }
            }
        }
        if (best == INT_MAX) printf("-1\n");
        else printf("%d\n", best);

        free(xor_left);
        free(cost_left);
        free(xor_right);
        free(cost_right);
    }

    free(a);
    return 0;
}

