        for (int b = 60; b >= 0; b--) {
            if ((a[i] >> b) & 1LL) {
                if (b > maxbit) maxbit = b;
                break;
            }
        }
    }

    /* After cheating, cheetah moves first.
       To guarantee cheater wins, initial position after modifications
       must be a losing Nim position, i.e. xor = 0.
       We may decrease each pile by at most 1, so choose subset S of piles
       with odd a[i] parity effect on xor:
         new_xor = xor ^ (xor of values t_i where t_i = 1 if pile decreased and a[i] changes by 1)
       Since decreasing by 1 toggles only bit 0 with borrows, more directly:
         need xor of chosen delta-values to equal original xor, where delta = a[i] ^ (a[i]-1)
       But simpler bitwise condition exists:
       Let highest set bit of original xor be k.
       Any pile changed must have bit k = 1 in delta, which happens iff a[i] has bit k = 1.
       Lower bits can be adjusted recursively; minimal number equals number of piles with bit k = 1
       needed odd? Actually to make xor zero by subtracting 0/1 from each pile, necessary and sufficient:
       count of piles having bit k set must be even after changes. Changing a pile with bit k set toggles bit k.
       To eliminate highest xor bit, need odd number of such changes.
       But any such change on pile with highest set bit exactly k also creates all lower bits 1 in delta suffix.
       Standard minimization reduces to:
         choose some piles with bit k set; xor of their lower parts must match lower bits target.
       Yet because every chosen pile contributes same bit k and arbitrary lower suffix from a[i],
       the minimum guaranteed number is exactly number of piles with highest xor bit set among all piles?
       Let's derive correctly instead by DP on xor impossible due size.

       Better observation:
       delta_i = a[i] ^ (a[i]-1) = 2^{t+1}-1 where t = trailing zeros of a[i].
       So available deltas are masks of form 1,3,7,15,...
       Need xor of selected deltas = xr, minimizing count.
       This is equivalent over prefix bits. Greedy from highest bit downward:
       To produce highest set bit k of xr, must select odd number of deltas with length > k,
       i.e. piles divisible by 2^k but not relevant? Specifically delta has bit k set iff a[i] divisible by 2^k.
       Since delta masks are nested, choosing one with highest bit h contributes all bits 0..h.
       Let c[h] = count of piles with delta highest bit h, i.e. v2(a[i]) = h.
       Need represent xr as xor of masks (2^{h+1}-1), each usable up to c[h] times, min count.
       Since parity only matters, usable if c[h] > 0 for odd count, extra pairs increase cost uselessly.
       Thus each h gives optional vector mask_h if c[h] odd/even? Wait can choose 0 or 1 mod2, possible iff count>=1.
       Since using 2 copies cancels xor and increases cost, never optimal. So each h usable at most once if c[h]>=1.
       Need min number of distinct h masks whose xor = xr.
       But multiple piles same h still only one useful. 
       Masks xor property: xor of masks for h in set gives number whose bit j = parity of count of selected h >= j.
       Let p_j be parity of selected masks with h >= j. Then result bits are p_j.
       Hence p_j = bit_j(xr), and selected indicator x_h = p_h ^ p_{h+1}.
       Therefore solution is unique:
         x_h = bit_h(xr) xor bit_{h+1}(xr), with bit beyond max =0.
       Need for every h with x_h=1, at least one pile having delta highest bit h, i.e. v2(a[i])=h.
       Answer = sum x_h.
    */

    long long ans = 0;
    int ok = 1;

    for (int h = 0; h <= 60; h++) {
        int bit_h = (int)((xr >> h) & 1LL);
        int bit_hp1 = (h == 60 ? 0 : (int)((xr >> (h + 1)) & 1LL));
        int need = bit_h ^ bit_hp1;
        if (need) {
            int found = 0;
            for (int i = 0; i < N; i++) {
                if (a[i] == 0) continue;
                int tz = 0;
                long long v = a[i];
                while ((v & 1LL) == 0) {
                    tz++;
                    v >>= 1;
                }
                if (tz == h) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                ok = 0;
                break;
            }
            ans++;
        }
    }

    if (!ok) printf("-1\n");
    else printf("%lld\n", ans);

    free(a);
    return 0;
}

