#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    // dp[carry]:
    // carry = whether lower bits caused a borrow from current bit to next bit
    // value = minimum stones removed so far
    //
    // We process bits independently from low to high.
    // For each pile and each bit, we may remove 1 from that pile or not.
    // Removing 1 affects bits through standard binary subtraction with borrow.
    //
    // Let x_i in {0,1} denote whether we remove one stone from pile i.
    // Final value is b_i = a_i - x_i.
    // We need xor of all b_i to be 0.
    //
    // Bit DP over borrow count parity:
    // For each pile at a given bit:
    //   if x_i = 0, outgoing borrow = 0, bit contributes original bit
    //   if x_i = 1, subtracting 1 from a_i:
    //      incoming borrow into bit is 1 until first 1-bit of a_i is consumed.
    // Equivalent local transition:
    //   starting with "still borrowing" = 1 for chosen piles, else 0.
    //
    // A simpler aggregate formulation:
    // For bit k, let z_k = number of piles with x_i=1 and all lower k bits of a_i are 0.
    // Then bit k of b_i equals bit_k(a_i) xor active_borrow_i, where
    // active_borrow_i means chosen pile still has borrow entering bit k.
    //
    // We can process counts by tracking only parity of active borrows, because xor bit only depends on parity.
    // But transition of active borrows to next bit depends on how many chosen piles have bit_k(a_i)=0 while active.
    // This requires more than parity globally.
    //
    // Instead, use classic linear DP by grouping piles by value modulo powers of two:
    // Observe removing 1 from pile i changes nim-sum by delta_i = a_i xor (a_i-1).
    // We need choose subset S with xor of delta_i equal initial xor X, minimizing |S|,
    // with restriction a_i > 0 for chosen piles.
    //
    // Because (a xor (a-1)) = 2^{t+1}-1 where t = ctz(a), for a>0.
    // So each pile contributes a mask of form (1<<(t+1))-1.
    // Let cnt[t] = number of piles with v2(a_i)=t.
    // Need minimum number chosen so xor of these masks equals X.
    //
    // Masks are prefix-ones. XOR of selected masks can be characterized by parities p_t of chosen counts from each t.
    // Result bit k equals parity of sum_{t>=k} p_t.
    // This mapping is invertible:
    // p_k = bit_k(X) xor bit_{k+1}(X), with highest p_H = bit_H(X).
    // Therefore required parity for each t is fixed.
    //
    // Minimum chosen count is sum over t of (required parity ? 1 : 0), provided cnt[t] allows that parity.
    // Since any larger same-parity count is unnecessary.
    //
    // Need enough bit range.
    long long X = 0;
    for (auto v : a) X ^= v;

    if (X == 0) {
        cout << 0 << '\n';
        return 0;
    }

    const int MAXB = 61;
    vector<int> cnt(MAXB, 0);
    for (long long v : a) {
        if (v == 0) continue;
        int t = __builtin_ctzll((unsigned long long)v);
        cnt[t]++;
    }

    int ans = 0;
    for (int t = 0; t < MAXB; ++t) {
        int bt = (X >> t) & 1LL;
        int bnext = (t + 1 < MAXB ? ((X >> (t + 1)) & 1LL) : 0);
        int needParity = bt ^ bnext;
        if (needParity) {
            if (cnt[t] == 0) {
                cout << -1 << '\n';
                return 0;
            }
            ans += 1;
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.util.*;

public class CheaterNim {
    static int n;
    static int[] a;
    static Map<String, Integer> memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        memo = new HashMap<>();
        int result = dfs(0, 0);
        System.out.println(result == Integer.MAX_VALUE ? -1 : result);
    }

    static int dfs(int idx, int xor) {
        if (idx == n) {
            return (xor == 0) ? 0 : Integer.MAX_VALUE / 2;
        }
        String key = idx + "," + xor;
        if (memo.containsKey(key)) return memo.get(key);

        // option 1: take 0 stone from this pile
        int ans = dfs(idx + 1, xor ^ a[idx]);
        // option 2: take 1 stone if possible
        if (a[idx] > 0) {
            int take = 1 + dfs(idx + 1, xor ^ (a[idx] - 1));
            ans = Math.min(ans, take);
        }
        memo.put(key, ans);
        return ans;
    }
}

