import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] a = new long[n];
        long xor = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextLong();
            xor ^= a[i];
        }

        // After cheating, cheetah still moves first.
        // To guarantee cheater wins, initial position for first player must be losing:
        // xor(after changes) == 0.
        //
        // Cheater may decrease each pile by at most 1.
        // Let x_i be 1 if we decrease pile i, else 0.
        // Need xor_i (a_i - x_i) = 0, minimizing sum x_i.
        //
        // DP over bits with carry/borrow from lower bits.
        // For each pile, subtracting 1 changes bits as:
        // if x_i=0: value unchanged
        // if x_i=1 and a_i>0: standard binary subtraction with borrow chain.
        // We process all piles bit by bit using count of active borrows.

        // dp[c] = minimum stones eaten after processing lower bits,
        // where c piles currently have borrow=1 into current bit.
        final int INF = 1_000_000_000;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        // Enough bits for ai up to long; +1 for final carry resolution
        for (int bit = 0; bit <= 61; bit++) {
            int ones = 0;
            int zeros = 0;
            for (int i = 0; i < n; i++) {
                if (((a[i] >> bit) & 1L) == 1L) ones++;
                else zeros++;
            }

            int[] ndp = new int[n + 1];
            Arrays.fill(ndp, INF);

            for (int c = 0; c <= n; c++) {
                if (dp[c] == INF) continue;

                // Among c piles with incoming borrow:
                // - if current bit of a is 0 -> result bit becomes 1, borrow continues
                // - if current bit of a is 1 -> result bit becomes 0, borrow stops
                //
                // Let k0 = number of borrowed piles among zero-bit piles.
                // Then borrowed piles among one-bit piles = c - k0.
                int low = Math.max(0, c - ones);
                int high = Math.min(c, zeros);

                for (int k0 = low; k0 <= high; k0++) {
                    int borrowedZero = k0;
                    int borrowedOne = c - k0;

                    // Resulting 1-bits at this bit:
                    // non-borrowed one-bit piles contribute 1: ones - borrowedOne
                    // borrowed zero-bit piles contribute 1: borrowedZero
                    int parity = ((ones - borrowedOne) + borrowedZero) & 1;

                    if (parity != 0) continue; // xor bit must be 0

                    // Next borrow count = borrowed zero-bit piles + newly started borrows
                    // Newly started borrows can only come from non-borrowed zero-bit piles
                    int availableStart = zeros - borrowedZero;

                    // Choose t new starts so that total eaten is minimized.
                    // Cost increases by t, next carry = borrowedZero + t.
                    // Since future feasibility depends on next carry, we try all t.
                    for (int t = 0; t <= availableStart; t++) {
                        int nc = borrowedZero + t;
                        int val = dp[c] + t;
                        if (val < ndp[nc]) ndp[nc] = val;
                    }
                }
            }

            dp = ndp;
        }

        // After all bits, no borrow may remain; also piles with a_i=0 cannot be decremented,
        // which is naturally enforced because an unresolved borrow would remain forever.
        int ans = dp[0];
        System.out.println(ans >= INF ? -1 : ans);
    }
}

