    n = int(input_data[0])
    a = list(map(int, input_data[1:n+1]))

    X = 0
    for x in a: X ^= x
    if X == 0:
        print(0)
        return

    # masks[i] = a[i] ^ (a[i]-1) for a[i] > 0
    mask_counts = defaultdict(int)
    for x in a:
        if x > 0:
            m = x ^ (x-1)
            mask_counts[m] += 1

    masks = list(mask_counts.keys())

    # BFS: find minimum number of masks (with count limits) XORing to X
    # Since counts can be large, treat each mask as available multiple times (up to count)
